#include <vector>
#include <algorithm>

class Solution {
public:
    long long maxMeetingEarnings(std::vector<std::vector<int>>& meetings, int gap) {
        std::sort(meetings.begin(), meetings.end(), [](auto const& a, auto const& b) {
            return a[1] < b[1];
        });

        int n = meetings.size();
        std::vector<long long> dp(n + 1, 0);
        std::vector<int> ends;
        for (auto const& m : meetings) ends.push_back(m[1]);

        for (int i = 1; i <= n; ++i) {
            int start = meetings[i - 1][0];
            int earn = meetings[i - 1][2];

            int idx = std::upper_bound(ends.begin(), ends.end(), start - gap) - ends.begin();
            dp[i] = std::max(dp[i - 1], earn + dp[idx]);
        }
        return dp[n];
    }
};

import java.util.*;

class Solution {
    public long maxMeetingEarnings(int[][] meetings, int gap) {
        Arrays.sort(meetings, (a, b) -> Integer.compare(a[1], b[1]));
        int n = meetings.length;
        long[] dp = new long[n + 1];
        int[] ends = new int[n];
        for (int i = 0; i < n; i++) ends[i] = meetings[i][1];

        for (int i = 1; i <= n; i++) {
            int start = meetings[i - 1][0];
            int earn = meetings[i - 1][2];

            int idx = bisectRight(ends, start - gap);
            dp[i] = Math.max(dp[i - 1], earn + dp[idx]);
        }
        return dp[n];
    }

    private int bisectRight(int[] arr, int target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int mid = l + (r - l) / 2;
            if (arr[mid] > target) r = mid;
            else l = mid + 1;
        }
        return l;
    }
}

function maxMeetingEarnings(meetings, gap) {
    meetings.sort((a, b) => a[1] - b[1]);
    const n = meetings.length;
    const dp = new Array(n + 1).fill(0);
    const ends = meetings.map(m => m[1]);

    for (let i = 1; i <= n; i++) {
        const [start, end, earn] = meetings[i - 1];

        let l = 0, r = n;
        const target = start - gap;
        while (l < r) {
            const mid = Math.floor((l + r) / 2);
            if (ends[mid] > target) r = mid;
            else l = mid + 1;
        }
        const idx = l;
        dp[i] = Math.max(dp[i - 1], earn + dp[idx]);
    }
    return dp[n];
}
